#!/usr/bin/env python3
from pathlib import Path
import shutil
import sys

ROOT = Path(__file__).resolve().parent
PROJECT = Path.cwd()
PAYLOAD = ROOT / "payload"

def fail(message: str) -> None:
    raise SystemExit(f"[SP Credits fix] {message}")

def backup(path: Path) -> None:
    target = path.with_suffix(path.suffix + ".bak-sp-credits-fix")
    if not target.exists():
        shutil.copy2(path, target)

def replace_one(rel: str, old: str, new: str, mode=1) -> None:
    path = PROJECT / rel
    if not path.exists():
        fail(f"Missing file: {rel}")
    text = path.read_text(encoding="utf-8")

    if mode == "all":
        if old not in text:
            if new in text:
                print(f"already  {rel}")
                return
            fail(f"Patch target not found in {rel}: {old[:100]!r}")
        backup(path)
        path.write_text(text.replace(old, new), encoding="utf-8")
        print(f"updated  {rel}")
        return

    occurrences = text.count(old)
    if occurrences == 0:
        if new in text:
            print(f"already  {rel}")
            return
        fail(f"Patch target not found in {rel}: {old[:100]!r}")
    if occurrences != 1:
        fail(f"Expected one target in {rel}, found {occurrences}: {old[:100]!r}")

    backup(path)
    path.write_text(text.replace(old, new, 1), encoding="utf-8")
    print(f"updated  {rel}")

def copy_payload(rel: str) -> None:
    src = PAYLOAD / rel
    dst = PROJECT / rel
    if not src.exists():
        fail(f"Patch payload missing: {rel}")
    dst.parent.mkdir(parents=True, exist_ok=True)
    if dst.exists() and dst.read_bytes() == src.read_bytes():
        print(f"already  {rel}")
        return
    if dst.exists():
        backup(dst)
    shutil.copy2(src, dst)
    print(f"replaced {rel}")


